"""Regenerate lib/merge.js from the SYNC block in public/index.html (single source of truth)."""
import pathlib, re
root = pathlib.Path(__file__).resolve().parents[1]
html = (root / "public/index.html").read_text(encoding="utf-8")
block = re.search(r"/\*SYNC:BEGIN\*/[\s\S]*?/\*SYNC:END\*/", html).group(0)
(root / "lib/merge.js").write_text(
    "// GENERATED by scripts/gen-merge.py from the SYNC block in public/index.html. Do not edit.\n"
    + block + "\n\nexport { mergeDoc, mergeMain, mergeQuiz, stampChanges, summarize, pickMain, pickQuiz, trackStat };\n",
    encoding="utf-8")
